use genewars_runtime::{zone_score_marker::*,landing::*,actor_activation::TrigTables};use std::io::{Read,Write};fn main(){let trig=TrigTables::generate_pinned().unwrap();let mut bytes=Vec::new();std::io::stdin().read_to_end(&mut bytes).unwrap();let mut output=Vec::new();for c in bytes.chunks_exact(16345){let m:&[u8;124]=c[..124].try_into().unwrap();let mut pool=[[0;81];200];for(i,r)in pool.iter_mut().enumerate(){r.copy_from_slice(&c[124+i*81..124+(i+1)*81]);}let p=&c[16324..];let count=i16::from_le_bytes(p[0..2].try_into().unwrap());let ground=i32::from_le_bytes(p[2..6].try_into().unwrap());let base=i32::from_le_bytes(p[6..10].try_into().unwrap());let shade=p[10];let owner=p[11]as i8;let divisor=i16::from_le_bytes(p[12..14].try_into().unwrap())as i32;let rng=LandingRng{seed:u16::from_le_bytes(p[14..16].try_into().unwrap()),ring:p[16],draw_count:u32::from_le_bytes(p[17..21].try_into().unwrap())};let head=LandingReference{index:7,kind:1};let plan=plan_one(m,&pool,count,base,divisor,owner,ground,shade,Some(ResolvedCellHead{identity:head}),1024,rng,trig.sine().try_into().unwrap(),trig.cosine().try_into().unwrap()).unwrap();let f=&plan.factory;pool[f.slot as usize]=f.after_nonpointer;for mut r in pool{r[31..39].fill(0);output.extend(r);}output.extend(f.pool_count_after.to_le_bytes());output.extend(f.slot.to_le_bytes());output.extend(f.animation_index.to_le_bytes());output.extend(plan.rng_after.seed.to_le_bytes());output.push(plan.rng_after.ring);output.extend(plan.rng_after.draw_count.to_le_bytes());for d in plan.draws{output.extend(d.journal_code.to_le_bytes());}let id=[f.slot as u8,(f.slot>>8)as u8,5];output.extend(id);output.extend(id);}std::io::stdout().write_all(&output).unwrap();}